node <<'NODE'
const assert = require('node:assert/strict');
const fs = require('node:fs');
const inventory = JSON.parse(fs.readFileSync('architecture/arc13/ui-text-candidates.json', 'utf8'));
const summary = inventory.summary;
assert.equal(inventory.schemaVersion, 4);
assert.equal(inventory.status, 'candidate-unreviewed');
assert.equal(summary.javascriptParseErrors, 0, 'JavaScript input must parse without errors');
assert.equal(inventory.parseErrors.length, 0);
assert.equal(summary.javascriptNotScannedSources, 0,
  'the normal AST-backed scan must run instead of HTML-only mode');
assert.equal(summary.unassignedOwnerSites, 0,
  'source-path technical ownership must be assigned');
assert.equal(summary.unassignedRouteSites, 0,
  'JavaScript sink routes must be assigned');
assert.equal(summary.primaryPageAuthoringUnresolvedOccurrences, 0);
assert.equal(summary.unreviewedOccurrences, inventory.entries.length,
  'generated candidates remain unreviewed');
assert(inventory.entries.every((entry) => entry.classification === 'unreviewed'));
const expectedOutputs = [
  { path: 'app/index.html', route: '/' },
  { path: 'app/about/index.html', route: '/about/' },
  { path: 'app/how-it-works/index.html', route: '/how-it-works/' }
];
assert.deepEqual(
  inventory.primaryPageAuthoringProvenance.outputs.map(({ path, route, status }) => ({ path, route, status })),
  expectedOutputs.map(({ path, route }) => ({ path, route, status: 'mapped' }))
);
for (const { path } of expectedOutputs) {
  const occurrences = inventory.entries.filter((entry) => entry.source === path);
  assert(occurrences.length > 0, `expected inventoried occurrences for ${path}`);
  assert(occurrences.every((entry) => entry.authoring?.status === 'mapped'),
    `every occurrence in ${path} must resolve to authoring provenance`);
}
assert.equal(summary.primaryPageAuthoringMappedOccurrences,
  inventory.entries.filter((entry) => entry.authoring?.status === 'mapped'
    && ['app/index.html', 'app/about/index.html', 'app/how-it-works/index.html'].includes(entry.source)).length);
console.log(JSON.stringify(summary, null, 2));
